// In mongos shell: enable sharding on a database
sh.enableSharding('mydb');

// Shard a collection by a HASHED key (best for even distribution)
sh.shardCollection('mydb.events', { userId: 'hashed' });
// Hashed sharding: MongoDB hashes userId, distributes evenly
// All writes go to random shards — no hotspots
// Downside: range queries on userId go to ALL shards

// Shard a collection by RANGE key (use when range queries are common)
sh.shardCollection('mydb.orders', { customerId: 1 });
// Range sharding: orders with nearby customerId go to same shard
// Good: orders.find({ customerId: { $gte: 'A', $lte: 'M' } }) → 1 shard
// Bad risk: if most writes have customerId starting with 'A', creates a hotspot

// Compound shard key (more cardinality, avoids hotspots)
sh.shardCollection('mydb.logs', { region: 1, timestamp: 1 });
// First field: 'region' scopes the shard. Second field: 'timestamp' distributes within region

// Assume collection is sharded by { userId: 'hashed' }

// TARGETED — includes shard key (userId)
// mongos routes to exactly ONE shard
const userOrders = await orders.find({ userId: 'user123' }).toArray();
// Fast: one network hop to one shard

// SCATTER-GATHER — no shard key in filter
// mongos sends to ALL shards, merges results
const pendingOrders = await orders.find({ status: 'pending' }).toArray();
// Slow: N network hops to N shards, results merged on mongos
// Gets worse as you add more shards!

// Best practice: always include the shard key in your most frequent queries
// Design shard key to match your highest-frequency query pattern

// Check if a query is targeted:
const plan = await orders.find({ userId: 'user123' }).explain();
console.log(plan.queryPlanner.winningPlan.shards.length); // 1 = targeted, N = scatter-gather

// BAD shard key: timestamp (monotonically increasing)
// All new events go to the shard holding the latest range
// → one shard is always the 'hot' shard receiving all new writes
sh.shardCollection('mydb.events', { timestamp: 1 });

// BAD shard key: _id with ObjectId
// ObjectId's first 4 bytes are a timestamp — same hotspot problem!
sh.shardCollection('mydb.events', { _id: 1 });

// GOOD: hashed _id — distributes writes evenly across all shards
sh.shardCollection('mydb.events', { _id: 'hashed' });
// MongoDB hashes the ObjectId, distributing writes randomly

// GOOD: compound with high-cardinality field first
// region is low-cardinality (8 regions) → use as zone partition
// userId is high-cardinality → distributes within each region
sh.shardCollection('mydb.events', { region: 1, userId: 'hashed' });
